/// Story 842: a process killed after a message's `AssistantMessageStarted`
/// and before its closing `AssistantMessage` leaves a text-free item.
/// Catches: that item rebuilding as an empty text block, which the
/// Anthropic Messages API refuses, so every later request of the resumed
/// session fails.
#[test]
fn a_message_killed_before_its_close_rebuilds_no_empty_text_block() {
    let mut log = Log::new();
    log.item(prompt("read it"));
    log.item(EventKind::AssistantMessageStarted);
    log.item(started(Some("call_a")));

    let (conversation, _) =
        conversation_from(&log.state).expect("a repairable history rebuilds");
    let empty: Vec<&Message> = conversation
        .messages()
        .iter()
        .filter(|message| {
            message
                .content
                .iter()
                .any(|block| matches!(block, ContentBlock::Text { text } if text.is_empty()))
        })
        .collect();
    assert!(empty.is_empty(), "empty text blocks: {empty:?}");
    assert!(
        conversation.messages().iter().any(|message| message
            .content
            .iter()
            .any(|block| matches!(block, ContentBlock::ToolUse { call_id, .. } if call_id == "call_a"))),
        "the call the killed generation made still survives"
    );
}

