                .content
                .iter()
                .any(|block| matches!(block, ContentBlock::Text { text } if text.is_empty()))
        })
        .collect();
    assert!(empty.is_empty(), "empty text blocks: {empty:?}");
    assert!(
        conversation.messages().iter().any(|message| message
            .content
            .iter()
            .any(|block| matches!(block, ContentBlock::ToolUse { call_id, .. } if call_id == "call_a"))),
        "the call the killed generation made still survives"
    );
